package com.bank.atm;

import java.util.logging.Logger;

public class CombinationCounter {

    private static final Logger log = Logger.getLogger(CombinationCounter.class.getName());

    public int countWays(int[] denominations, int amount) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;                                     // one way to make zero: take nothing
        for (int coin : denominations) {               // coin loop OUTSIDE ⇒ combinations
            for (int a = coin; a <= amount; a++) {
                dp[a] += dp[a - coin];                  // extend every smaller total
            }
        }
        int result = dp[amount];
        log.info(() -> "Amount " + amount + " has " + result + " combinations");
        return result;
    }
}
