package com.bank.atm;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CoinChangeIIDemo {

    private static final Logger log = Logger.getLogger(CoinChangeIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — ATM Combination Planner (Coin Change II)");
        CombinationCounter counter = new CombinationCounter();
        log.info("5 with {1,2,5} → " + counter.countWays(new int[]{1, 2, 5}, 5)); // 4
        log.info("3 with {2} → " + counter.countWays(new int[]{2}, 3));           // 0
    }
}
